mapper.select:
SELECT 
FROM t_book

ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE t_book
name = #{name}, author = #{author}, cover_url = #{coverUrl}, category = #{category}, intro = #{intro}, status = #{status}, word_count = #{wordCount}, latest_chapter_id = #{latestChapterId}, latest_chapter_name = #{latestChapterName}, chapter_count = #{chapterCount}, source_name = #{sourceName}, source_url = #{sourceUrl}, info_url = #{infoUrl}, remark = #{remark}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE t_book
SET chapter_count = (SELECT COUNT(1) FROM t_chapter c WHERE c.book_id = #{bookId}),
    latest_chapter_id = (SELECT c.id FROM t_chapter c WHERE c.book_id = #{bookId}
                         ORDER BY c.chapter_no DESC LIMIT 1),
    latest_chapter_name = (SELECT c.title FROM t_chapter c WHERE c.book_id = #{bookId}
                           ORDER BY c.chapter_no DESC LIMIT 1),
    update_time = CURRENT_TIMESTAMP
WHERE id = #{bookId}
